{
  "case_id": "xsu_sg_013_specialist_declaration",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret siger, at UDK kan bede om en speciallægeerklæring, når der er behov for yderligere oplysninger, eller når en afgørelse ikke kan træffes ud fra de foreliggende oplysninger. Det er en for bred og upræcis trigger. Vejledningen kræver, at det sker i særlige tilfælde, og at den indsendte lægefaglige dokumentation ikke i tilstrækkelig grad beskriver arten og graden af funktionsnedsættelsen. Svaret nævner hverken 'særlige tilfælde' eller de konkrete eksempler."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Det første kritiske element er kun delvist med, fordi 'særlige tilfælde' og 'art og grad ikke tilstrækkeligt beskrevet' mangler. Det andet kritiske element mangler helt: ingen af de fire eksempelgrupper er nævnt. De er symptomintensitet/-hyppighed, uoverensstemmelse mellem lægeoplysninger og ansøgerens beskrivelse, tvivl om behandling og prognose samt tvivl om daglig funktion kontra ferieperioder."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret handler direkte om, hvornår UDK kan anmode om en speciallægeerklæring. Det er generelt, men besvarer spørgsmålet."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde som lovbestemmelse, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke citeret nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, som kan støtte påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en trigger om 'behov for yderligere oplysninger' og 'ikke muligt at træffe en beslutning på baggrund af de oplysninger, der allerede er til rådighed'. Den står ikke i vejledningen om speciallægeerklæring, som i stedet kræver utilstrækkelig beskrivelse af art og grad. Formuleringen kan ligne § 37, stk. 5, men den er brugt som tærskel for speciallægeerklæring uden støtte."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret udelader forbeholdet 'i særlige tilfælde'. Det udelader også, at eksemplerne er illustrative, og at kravet om 'stor tvivl' bevares i eksemplerne. Det gør muligheden bredere end kilden."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: behov for yderligere oplysninger, og hvis de eksisterende oplysninger ikke rækker, kan der bedes om erklæringen. Det er simpelt, men der er ingen modsigelser."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "Svaret bruger 'kan' og gør ikke erklæringen obligatorisk eller automatisk. Det udelader dog 'i særlige tilfælde'. Det er behandlet under C08, og modaliteten er ikke gjort absolut."
    }
  },
  "xhaile_coverage": {
    "A74": {
      "label": "partial",
      "reason": "Svaret dækker, at UDK kan indhente en speciallægeerklæring, og at det knytter sig til behov for yderligere oplysninger om handicappet. Det udelader 'i særlige tilfælde', den præcise betingelse (utilstrækkelig beskrivelse af art og grad) og alle fire eksempler."
    }
  },
  "overall_notes": "Svaret er generelt og kildeløst. Det rammer kun den grove idé om, at UDK kan bede om en erklæring, når oplysningerne er utilstrækkelige. Det mangler 'særlige tilfælde', art og grad-kriteriet og de fire eksempelgrupper, og det tilføjer en bredere trigger uden kildestøtte."
}

